def is_valid_address(address):
    # Check if the address starts with "k9://"
    if not address.startswith("k9://"):
        return False

    # Split the address into the host part and port part
    # The address is in theformat "k9://HOST:PORT", so we split on ":"
    parts = address.split(":", 1)  # Split into two parts at the first ":"
    if len(parts) != 2:
        return False  # There should be exactly two parts after splitting

    host_part = parts[0][5:]  # Remove the "k9://" prefix
    port_part = parts[1]

    # Check if the host part is valid
    # Host is made of 2 to 4 labels separated by single dots
    # Each label is 1 to 8 characters long and contains only lowercase letters and digits
    # A label may not start with a digit
    if not host_part:
        return False
    labels = host_part.split(".")
    if len(labels) < 2 or len(labels) > 4:
        return False
    for label in labels:
        if not (1 <= len(label) <= 8):
            return False
        if not (label[0].isdigit() or label[0].isalpha()):
            return False
        for char in label:
            if not (char.islower() or char.isdigit()):
                return False

    # Check if the port is valid
    # PORT is required. It is written in decimal without leading zeros and must be between 1024 and 49151 (inclusive)
    if not port_part.isdigit():
        return False
    port = int(port_part)
    if not (1024 <= port <= 49151):
        return False

    # Nothing may follow the port
    if address.endswith(":"):
        return False

    return True
```

The function checks if the address starts with "k9://", splits it into host and port parts, and then validates the host and port according to the rules. It returns True if the address is valid, and False otherwise.

